    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] sk = new String[n];
        long[] sv = new long[n];
        int[] sp = new int[n];
        for (int i = 0; i < n; i++) {
            sk[i] = st.nextToken();
            sv[i] = Long.parseLong(st.nextToken());
            sp[i] = Integer.parseInt(st.nextToken());
        }
        int m = Integer.parseInt(st.nextToken());
        String[] tk = new String[m];
        long[] tv = new long[m];
        int[] tp = new int[m];
        for (int i = 0; i < m; i++) {
            tk[i] = st.nextToken();
            tv[i] = Long.parseLong(st.nextToken());
            tp[i] = Integer.parseInt(st.nextToken());
        }
        StringBuilder sb = new StringBuilder();
        for (String s : mergeTrees(sk, sv, sp, tk, tv, tp)) sb.append(s).append('\n');
        System.out.print(sb);
    }
}
